import * as React from "react"
import { MoreHorizontal } from "lucide-react"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription,
  AlertDialogFooter, AlertDialogTitle } from "@atlas/ui-web/compositions/AlertDialog/AlertDialog"
import { Card, CardContent } from "@atlas/ui-web/compositions/Card/Card"
import { Dialog, DialogBody, DialogClose, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@atlas/ui-web/compositions/Dialog/Dialog"
import { Field } from "@atlas/ui-web/compositions/Field/Field"
import { toast } from "@atlas/ui-web/compositions/Toast/Toast"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@atlas/ui-web/patterns/DropdownMenu/DropdownMenu"
import { Avatar } from "@atlas/ui-web/primitives/Avatar/Avatar"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@atlas/ui-web/primitives/Select/Select"
import { Skeleton } from "@atlas/ui-web/primitives/Skeleton/Skeleton"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@atlas/ui-web/primitives/Table/Table"

const ROLES = ["Owner", "Admin", "Member"] as const
type Role = (typeof ROLES)[number]
type Member = { id: string; name: string; email: string; role: Role; status: "Active" | "Pending" }

const title = { fontSize: "var(--atlas-text-h1)" }
const muted = { fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }

export function MembersPage({ members, currentUserId, loading, onInvite, onChangeRole, onRemove, onResend, onRevoke }: {
  members: Member[]
  currentUserId: string
  loading?: boolean
  /** Rejects with a readable reason on failure. */
  onInvite: (email: string, role: Role) => Promise<void>
  /** Saves at once. Rejects with a readable reason on failure. */
  onChangeRole: (id: string, role: Role) => Promise<void>
  onRemove: (id: string) => Promise<void>
  onResend: (id: string) => void
  onRevoke: (id: string) => void
}) {
  const [inviteOpen, setInviteOpen] = React.useState(false)
  const [email, setEmail] = React.useState("")
  const [inviteRole, setInviteRole] = React.useState<Role>("Member")
  const [removing, setRemoving] = React.useState<Member | null>(null)
  const [saving, setSaving] = React.useState<string | null>(null)

  const owners = members.filter((m) => m.role === "Owner" && m.status === "Active")
  const lastOwner = owners.length === 1 ? owners[0] : null

  const changeRole = async (m: Member, role: Role) => {
    setSaving(m.id)
    try {
      await onChangeRole(m.id, role)
      toast({ title: `${m.name} is now ${role === "Admin" ? "an" : "a"} ${role}` })
    } catch (e) {
      // The Select is controlled by `members`, so it stays on the previous role.
      toast({ variant: "danger", title: "Role not changed", description: e instanceof Error ? e.message : "Try again." })
    } finally {
      setSaving(null)
    }
  }

  const invite = async () => {
    try {
      await onInvite(email, inviteRole)
      setInviteOpen(false)
      setEmail("")
      toast({ title: `Invite sent to ${email}` })
    } catch (e) {
      toast({ variant: "danger", title: "Invite not sent", description: e instanceof Error ? e.message : "Try again." })
    }
  }

  return (
    <div style={{ display: "grid", gap: "var(--atlas-spacing-4)", maxInlineSize: "48rem" }}>
      <header style={{ display: "flex", flexWrap: "wrap", alignItems: "center", justifyContent: "space-between", gap: "var(--atlas-spacing-3)" }}>
        <h1 style={title}>Members</h1>
        <Dialog open={inviteOpen} onOpenChange={setInviteOpen}>
          <DialogTrigger><Button variant="primary">Invite member</Button></DialogTrigger>
          <DialogContent size="md">
            <DialogHeader><DialogTitle>Invite member</DialogTitle></DialogHeader>
            <DialogBody>
              <DialogDescription>
                They will get an email with a link to join. Owners can manage billing; Admins can manage members; Members can edit content.
              </DialogDescription>
              <Field label="Email address" required>
                {(control) => <Input {...control} type="email" value={email} onChange={(e) => setEmail(e.target.value)} autoComplete="off" />}
              </Field>
              <Field label="Role" required>
                {(control) => (
                  <Select value={inviteRole} onValueChange={(v) => setInviteRole(v as Role)}>
                    <SelectTrigger id={control.id}><SelectValue /></SelectTrigger>
                    <SelectContent>{ROLES.map((r) => <SelectItem key={r} value={r}>{r}</SelectItem>)}</SelectContent>
                  </Select>
                )}
              </Field>
            </DialogBody>
            <DialogFooter>
              <DialogClose><Button variant="outline">Cancel</Button></DialogClose>
              <Button variant="primary" disabled={!email.trim()} onClick={invite}>Send invite</Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </header>

      {lastOwner && (
        <Alert
          variant="info"
          title={`${lastOwner.name} is the only Owner`}
          description={`Make another member an Owner before changing this role or removing ${lastOwner.name.split(" ")[0]}.`}
        />
      )}

      {loading ? (
        // Loading covers the list only; the header and the Invite button stay.
        <div role="status" aria-label="Loading members" style={{ display: "grid", gap: "var(--atlas-spacing-4)" }}>
          <Skeleton />
          <Skeleton />
          <Skeleton />
          <Skeleton />
        </div>
      ) : (
        <Card variant="outlined">
          <CardContent>
            <Table aria-label="Members">
              <TableHeader>
                <TableRow>
                  <TableHead>Member</TableHead>
                  <TableHead>Role</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead><span style={{ position: "absolute", inlineSize: 1, blockSize: 1, overflow: "hidden", clipPath: "inset(50%)" }}>Actions</span></TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {members.map((m) => {
                  const pending = m.status === "Pending"
                  const protectedOwner = m.id === lastOwner?.id
                  const reasonId = `owner-reason-${m.id}`
                  return (
                    <TableRow key={m.id}>
                      <TableCell>
                        <span style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-2)" }}>
                          <Avatar size="sm" initials={m.name.split(" ").map((p) => p[0]).join("")} alt="" />
                          <span style={{ display: "grid" }}>
                            <span>{m.name}{m.id === currentUserId && " (You)"}</span>
                            <span style={muted}>{m.email}</span>
                          </span>
                        </span>
                      </TableCell>
                      <TableCell>
                        {pending ? (
                          <span style={muted}>Invited as {m.role}</span>
                        ) : (
                          <Select value={m.role} onValueChange={(v) => changeRole(m, v as Role)} disabled={protectedOwner || saving === m.id}>
                            <SelectTrigger size="md" aria-label={`Role for ${m.name}`} aria-describedby={protectedOwner ? reasonId : undefined}>
                              <SelectValue />
                            </SelectTrigger>
                            <SelectContent>{ROLES.map((r) => <SelectItem key={r} value={r}>{r}</SelectItem>)}</SelectContent>
                          </Select>
                        )}
                        {protectedOwner && <span id={reasonId} style={{ position: "absolute", inlineSize: 1, blockSize: 1, overflow: "hidden", clipPath: "inset(50%)" }}>The only Owner cannot be demoted.</span>}
                      </TableCell>
                      <TableCell><Badge variant={pending ? "warning" : "success"} size="md">{m.status}</Badge></TableCell>
                      <TableCell align="end">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="md" iconOnly aria-label={`More actions for ${m.name}`}><MoreHorizontal /></Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent>
                            {pending ? (
                              <>
                                <DropdownMenuItem onSelect={() => onResend(m.id)}>Resend invite</DropdownMenuItem>
                                <DropdownMenuItem destructive onSelect={() => onRevoke(m.id)}>Revoke invite</DropdownMenuItem>
                              </>
                            ) : (
                              <DropdownMenuItem destructive disabled={protectedOwner} onSelect={() => setRemoving(m)}>Remove from workspace</DropdownMenuItem>
                            )}
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  )
                })}
              </TableBody>
            </Table>
            {members.length <= 1 && <p style={muted}>Invite people to share this workspace.</p>}
          </CardContent>
        </Card>
      )}

      <AlertDialog open={removing !== null} onOpenChange={(open) => { if (!open) setRemoving(null) }}>
        <AlertDialogContent variant="destructive">
          <AlertDialogTitle>{`Remove ${removing?.name}?`}</AlertDialogTitle>
          <AlertDialogDescription>
            {`${removing?.name} will lose access to this workspace and its projects immediately. Their work stays. You can invite them again later.`}
          </AlertDialogDescription>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={() => removing && onRemove(removing.id)}>{`Remove ${removing?.name.split(" ")[0]}`}</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

